# aeneid-041 draft. Drafted from the Latin and grammar only. t is cut from the edition, never typed.
TITLE = 'Preces Aeneae. Ramus aureus. Misenus'
TITLE_EN = "Aeneas's Plea, the Golden Bough and Misenus — Aeneid VI.98–189"
PART = "Aeneas's Plea, the Golden Bough and Misenus (VI.98–189)"
ABOUT = """The Sibyl, still in the grip of the god, chants her riddling answer, and as the frenzy leaves her Aeneas speaks. He is not afraid of any new trouble; he has looked ahead at all of it. He asks one thing: to go to the door of the king below and see his dear father, whom he carried out through fire and enemy and who shared every sea with him; he appeals to Orpheus, to Pollux, to Theseus and Hercules, and to his own descent from Jupiter. The Sibyl replies that the way down to Avernus is open at every hour, but to turn back and come out to the upper air is the real work, and few have done it. She tells him that a golden bough hidden in a shady tree is Proserpina's due, that it will come away easily if the fates call him and by no force otherwise, and that meanwhile the body of a friend of his lies unburied and defiles the whole fleet: he must bury it first, and bring black victims. Aeneas goes out sad, with Achates, wondering whom she meant, and finds Misenus dead on the shore: Hector's trumpeter, later Aeneas's man, drowned by a jealous Triton when he challenged the gods with his conch, if the tale is to be believed. The Trojans weep and cut timber in the old forest for the pyre, and Aeneas, working among them, prays that the golden bough may show itself to him in so great a wood, since the seer has spoken the truth about Misenus."""
U = [
(100, 'involvens:',
 """With such words spoken from the shrine the Cumaean Sibyl
chants dreadful riddles and bellows back in the cave,
wrapping truths in darkness:""",
 """Such were the words, and from the inner shrine the Cumaean Sibyl chanted her dreadful riddles and roared them back from the cave, veiling the truth in dark sayings:""",
 """A new paragraph, and no break in the scene: the 'talibus… dictis' are Aeneas's prayer, an ablative absolute, 'such words having been spoken'. 'Adyto' is the Greek 'adyton', the innermost shrine, no place for the uninitiated. 'Ambages' are riddling windings of speech, 'canit' is 'chants', and 'remugit' is 'bellows back', the 're-' being an echo from the cave. 'Antro' is an ablative of place with no preposition, a poetic habit you'll see constantly. 'Obscuris vera involvens' is a present participle, 'rolling truths up in dark things'; the colon opens the next line."""),
(101, 'Apollo.',
 """those reins for the raving one
shakes, and goads beneath her breast turns Apollo.""",
 """Apollo shakes the reins over her as she raves, and twists the goads deep beneath her breast.""",
 """The picture is of a driver mastering a horse: 'frena' are the bit and reins, 'stimulos' the goads, both used by the god on the 'furenti', a dative of the present participle, 'for her who raves'. 'Ea frena' is 'those reins' (a neuter plural), and Apollo, held back to the last word, is the subject of both verbs."""),
(103, 'heros:',
 """As soon as the frenzy gave way and the raving mouth grew still,
begins Aeneas the hero:""",
 """As soon as the frenzy left her and her wild lips were still, the hero Aeneas began:""",
 """'Ut primum' is 'as soon as'. 'Quierunt' is the contracted perfect of 'quiesco', for 'quievērunt'; 'ora' is the plural 'mouth', as often in poetry. 'Incipit' is a historic present, 'begins', with 'heros' (a Greek nominative) in apposition to Aeneas. The colon opens his speech."""),
(104, 'surgit;',
 """“No shape of labours,
O maiden, new to me or unexpected rises;""",
 """“No form that trouble can take, maiden, rises before me new or unforeseen;""",
 """The opening mark begins Aeneas's speech, which runs to 123 and is closed there. 'Ulla laborum… facies' is 'any shape of toils' set round the vocative: 'laborum' is a genitive plural, 'facies' the nominative subject, and the verb 'surgit' stands last. 'Mi' is 'mihi', a dative of reference, 'to me'. 'Inopinave' is 'inopina' with the enclitic '-ve', 'or unlooked-for'."""),
(105, 'peregi.',
 """all things I have foreseen and in mind with myself beforehand gone through.""",
 """I have foreseen it all, and lived through it in my own mind beforehand.""",
 """'Praecepi' is 'I have anticipated', a perfect of 'praecipio'; 'peregi' is 'I have gone through' (from 'perago'), and 'ante' is an adverb, 'beforehand'. 'Animo mecum' is 'in mind, with myself', a pleonasm which stresses that he has rehearsed it alone."""),
(106, 'oro:',
 """One thing I ask:""",
 """One thing I ask:""",
 """The colon opens the request, which is a long sentence with the 'quando' clause set inside it. 'Oro' is 'I ask' (the verb takes no 'ut' here: its wish comes as a plain subjunctive, 'contingat', 'doceas', 'pandas')."""),
(109, 'contingat;',
 """since here the door of the infernal king
is said to be, and the shadowy marsh with Acheron poured back,
to go to the sight of my dear father and face
may it befall;""",
 """since the gate of the king below is said to stand here, and the dark marsh where Acheron wells up again, may it be granted me to go before my dear father's eyes and look upon his face;""",
 """'Quando' here is causal, 'since', the old sense. 'Hic' is 'here', at Cumae and Avernus. 'Inferni… regis' is the king of the lower world, Dis or Pluto. 'Acheronte refuso' is an ablative absolute, with the participle of 'refundo', 'Acheron having been poured back' or 'overflowed': the marsh is formed where the river of the dead wells up again to the surface. 'Contingat' is 'may it befall', impersonal with 'ire' as its subject; 'ad conspectum… et ora' are 'to the sight and the face', both after 'ad', with 'cari genitoris' a genitive depending on the pair. It is a wish stated without 'ut' (parataxis)."""),
(109, 'pandas.',
 """may you teach the way and the holy doors throw open.""",
 """Teach me the road, and throw wide the sacred doors.""",
 """'Doceas' and 'pandas' are present subjunctives of request, in parallel with 'contingat', with 'ut' left out. 'Pandas' is 'spread open'. 'Sacra ostia' are 'sacred doors', holy because they belong to the powers below."""),
(111, 'recepi;',
 """Him I through flames and a thousand following missiles
snatched away on these shoulders, and from the midst of the enemy took back;""",
 """Him I carried on these shoulders out through the flames and a thousand spears that pressed upon us, and took him back from the midst of the foe;""",
 """'Illum' is Anchises, put first for stress. 'Per flammas et mille sequentia tela' is 'through flames and a thousand missiles following', 'sequentia' a present participle in the neuter plural: the weapons were still pursuing. 'Eripui' is 'I snatched out', 'his umeris' (ablative of means) 'on these shoulders', and 'recepi' is 'I took back', 'I got him back'. The reference is to the flight from burning Troy."""),
(114, 'senectae.',
 """he, accompanying my journey, all seas with me
and all threats of the sea and sky was bearing,
feeble, beyond strength and the lot of old age.""",
 """He journeyed with me, and with me bore every sea and every menace of ocean and sky, frail as he was, beyond the strength and the lot that old age allows.""",
 """'Comitatus' is the perfect participle of the deponent 'comitor', with an active sense, 'having accompanied', governing 'iter' as an accusative. 'Maria omnia… omnes… minas' is 'all seas… all threats', 'pelagi… caelique' being genitives, 'of sea and of sky'. 'Invalidus' is 'weak', 'frail'. 'Vires ultra sortemque senectae' is 'beyond the strength and the lot of old age', with the preposition after its noun."""),
(116, 'dabat.',
 """Nay more, that I should as suppliant seek you and approach your threshold,
the same one praying was giving charges.""",
 """Indeed it was he who, in his prayers, charged me to come as a suppliant and seek you, and to approach your threshold.""",
 """'Quin' is 'nay more', 'indeed'. 'Ut… peterem… adirem' is an indirect command after 'mandata dabat', 'was giving charges', and the imperfect makes it a repeated bidding. 'Idem' is 'the same man', Anchises, who both made the journey and urged it; 'orans' is 'praying', 'entreating'. 'Supplex' is a predicative adjective, 'as a suppliant'."""),
(118, 'Avernis;—',
 """Of son and of father,
kindly one, I pray, have pity; for you can do all things, nor you
in vain over the Avernian groves Hecate set;""",
 """Take pity, kind one, I beg, on a son and on his father — for you have power over everything, and not for nothing did Hecate set you over the groves of Avernus.""",
 """'Miserere' is the imperative of the deponent 'misereor' and takes a genitive, here 'gnati patrisque', 'of son and of father': 'gnati' is an old form of 'nati'. 'Alma' is 'kindly', 'nourishing', a title for a goddess or her priestess. Greenough prints the dash with no space after it, so the two sentences are kept as one unit; the dash opens a parenthesis. 'Potes… omnia' is 'you can do all things'. 'Lucis… Avernis' is a dative, the 'groves of Avernus', after 'praefecit', 'put in charge of'; Hecate is the goddess of the lower world, and is a name of the goddess whom the Sibyl serves as priestess. 'Nequiquam' is 'in vain', and 'nec… nequiquam' is a double negative, 'not in vain'. The dash closes the parenthesis."""),
(122, 'totiens.',
 """if Orpheus could summon the shades of his wife,
relying on the Thracian lyre and tuneful strings,
if his brother Pollux by alternate death redeemed,
and goes and returns the road so often.""",
 """If Orpheus could call up the shades of his wife, trusting in his Thracian lyre and its tuneful strings; if Pollux ransomed his brother by dying in turn, and travels the road, going and coming, so many times —""",
 """These 'si' clauses carry on from 'miserere': 'if they could, then (grant it) to me'; the main clause is never spoken, and the thought runs on into the next question. 'Manes' (Greenough's capital) are the spirits of the dead; 'arcessere' is 'to summon' (the Latin Library has 'accersere', the same word); 'coniugis' is Orpheus's wife, Eurydice. 'Threïcia' has a diaeresis in Greenough and is the adjective 'Thracian'; 'fretus' takes the ablative 'cithara fidibusque canoris'. Pollux, the immortal twin, 'redeemed' his mortal brother Castor 'by alternate death', the two sharing death and life by turns; 'itque reditque viam' has an accusative of the way travelled. For the scansion: 'Orpheus' is two syllables, the Greek 'eu' being a diphthong."""),
(123, 'Alciden?',
 """Why Theseus, great
why should I mention Alcides?""",
 """Why speak of Theseus? Why of mighty Hercules?""",
 """'Thesea' is a Greek accusative; 'Alciden' is the Greek accusative of the patronymic 'Alcides', 'descendant of Alcaeus', Hercules. 'Quid memorem' is a deliberative subjunctive, 'why should I mention?', repeated for emphasis; 'magnum' belongs with 'Alciden'. Both heroes had gone down to the underworld and returned."""),
(123, 'summo.”',
 """And to me also a lineage from Jupiter on high.”""",
 """And I too trace my line from Jove on high.”""",
 """'Mi' is 'mihi', and 'et mi genus' is a dative of possession, 'to me also there is a descent' (you'll see this constantly, as with 'sunt mihi'). 'Iove summo' is 'highest Jove'; the closing mark ends Aeneas's speech, which began at 103. The line runs through Dardanus, the ancestor of Troy's kings, a son of Jupiter; Aeneas's mother Venus was a daughter of Jupiter too."""),
(125, 'vates:',
 """With such words he was praying, and the altars he was holding,
when thus began to speak the seer:""",
 """So he prayed, and held the altars, when the seer began to speak:""",
 """A new paragraph. 'Talibus… dictis' is an ablative of means, 'with such words', and 'orabat… tenebat' are imperfects, 'was praying… was holding', so the 'cum' clause breaks in on a continuing action. 'Orsa' is the perfect participle of the deponent 'ordior', 'having begun', with 'est' left out: 'orsa loqui', 'began to speak', and 'vates' is the Sibyl."""),
(126, 'Averno;',
 """“Sprung from the blood of gods,
Trojan, Anchises' son, easy the going-down to Avernus;""",
 """“Scion of the blood of gods, Trojan son of Anchises, to go down to Avernus costs no effort;""",
 """The opening mark begins the Sibyl's speech, and Greenough prints it running on to 155. 'Sate' is the vocative of 'satus', 'sown', 'sprung', followed by 'sanguine' as an ablative of origin; 'divom' is the old genitive plural of 'deus' (see 'divom' in the glossary), 'of gods'. 'Tros… Anchisiade' is 'Trojan son of Anchises', 'Anchisiade' a Greek vocative (patronymic); 'Tros' is the singular noun 'a Trojan'. 'Descensus' is a verbal noun, 'the going down', with 'Averno' as a dative of direction, 'to Avernus'; 'est' is left out. Avernus is the lake by Cumae that gives access to the lower world."""),
(127, 'Ditis;',
 """nights and days lies open of black Dis the door;""",
 """the door of gloomy Dis is never shut, by night or by day;""",
 """'Noctes atque dies' is an accusative of duration, 'through nights and days', which gives 'at every hour'. 'Patet' is 'lies open', and its subject is 'ianua', 'door', set between 'atri' and 'Ditis': Dis is Pluto, and 'atri' is 'black', 'gloomy'. The verb is singular because its subject 'ianua' is."""),
(129, 'est.',
 """but to call back the step and to escape out to the upper airs,
this the work, here the hardship is.""",
 """But to turn your step back and win out to the air above — there is the real work of it, there the hardship.""",
 """'Revocare gradum' is 'to call back the step', to retrace the way; 'superas… ad auras' are 'the upper airs', the world of the living above; 'evadere' is 'to get out', 'to escape'. The two infinitives are the subject of the clause, summed up by 'hoc', with the nouns 'opus' and 'labor' as predicates: 'hoc opus, hic labor est' is a short clause with 'hoc' and 'hic' pointing at the phrase just spoken, the verb 'est' at the end. One of the best-known lines in the poem."""),
(131, 'potuere.',
 """Few, whom a kindly Jupiter has loved,
or burning virtue has lifted to the heavens,
born of gods, have been able.""",
 """Few have done it: those a favouring Jupiter loved, or whom blazing valour lifted to the heavens, children of gods.""",
 """'Pauci' is the subject of 'potuere' ('potuerunt', the usual '-ere' for '-erunt'), with the thing they were able to do, 'revocare gradum', understood from the line before. 'Aequus' is 'favourable', 'kindly'. 'Ardens… virtus' is 'burning valour', and 'evexit ad aethera' is 'carried up to the sky'. 'Dis' is 'diis', the dative or ablative plural of 'deus', and 'dis geniti' is 'born of gods', which stands in apposition to 'pauci' and may be taken with both kinds of person named."""),
(132, 'atro.',
 """Hold all the middle parts forests,
and Cocytus, gliding, goes round with its dark winding.""",
 """Forests hold all the ground between, and Cocytus, gliding in its dark windings, wraps itself around it.""",
 """'Media omnia' is 'all the middle parts', the whole region between the upper air and the depths. 'Silvae' is the subject, and 'tenent' is 'hold'. 'Sinu… atro' is an ablative, 'with dark curve', framing 'labens circumvenit'; Cocytus is a river of the lower world, whose name means 'wailing'."""),
(136, 'prius.',
 """But if so great a love is to your mind, if so great a desire,
twice to swim the Stygian lakes, twice to see black
Tartarus, and it pleases to indulge a mad labour,
take what must be done first.""",
 """But if you feel so great a love, so great a longing, to cross the Stygian lakes twice and twice look on black Tartarus, and it pleases you to give way to a mad task, then hear what must be done first.""",
 """'Quod si' is 'but if', with 'quod' a connecting relative. 'Menti' is a dative of possession: 'est menti', 'there is in your mind'. 'Bis' is 'twice' (once now, alive, and once more at death, as the line is usually explained). 'Innare', 'videre' and 'indulgere' are the infinitives that depend on 'amor' and 'cupido'. 'Innare' is 'to swim into', 'to sail over', with 'Stygios… lacus', the waters of the Styx; 'nigra… Tartara' is a neuter plural. 'Iuvat' is impersonal with an infinitive, and 'insano… labori' is dative after 'indulgere'. 'Accipe, quae peragenda prius' is 'hear what is to be done first', 'sunt' left out."""),
(138, 'sacer;',
 """Lies hidden in a shady tree
a golden both in leaves and in pliant twig bough,
to Juno of the lower world called sacred;""",
 """There lies hidden in a shadowy tree a bough of gold — gold in its leaves and in its supple shoot — which is called sacred to the Juno of the underworld;""",
 """This is the first mention of the golden bough, 'ramus', which the Sibyl will say must be taken. 'Latet' is 'lies hidden', 'arbore opaca' an ablative of place. 'Aureus et foliis et lento vimine' has 'et… et' for 'both… and', ablatives of respect, 'golden in leaves and in pliant twig'. 'Iunoni infernae' is Juno of the lower world, the queen of the dead, whom 142 names as Proserpina; 'dictus sacer' takes the dative, 'said to be sacred to'."""),
(139, 'umbrae.',
 """this the whole grove covers,
and in dim valleys enclose it shades.""",
 """A whole grove screens it, and shadows close it in among dark, steep-sided valleys.""",
 """'Omnis' is 'whole', with 'lucus', 'grove'; 'hunc' is the bough. 'Obscuris… convallibus' is 'in dark valleys', where the shadows are the subject, 'umbrae', held back to the end."""),
(141, 'fetus.',
 """But not before is it granted of earth the hidden places to enter,
than anyone has plucked from the tree the gold-haired growth.""",
 """But no one is allowed to enter the hidden places of the earth until he has plucked the golden-haired shoot from its tree.""",
 """'Datur… subire' is 'it is given to enter', impersonal, with 'operta' (a neuter plural participle) as 'the hidden places'. 'Non ante… quam… decerpserit' is 'not before… than anyone has plucked'; 'decerpserit' is a perfect subjunctive (of anticipation after 'quam'), though it could also be read as a future perfect, and 'quis' is 'anyone'. 'Auricomos… fetus' is 'gold-haired offspring', a compound adjective of the kind Virgil takes from Greek, and 'fetus' here means the growth on the tree, the bough."""),
(143, 'instituit.',
 """This for herself, fair Proserpina, to be borne her own gift
has ordained.""",
 """Fair Proserpina has ordained that this be brought to her as her own gift.""",
 """'Hoc' is the bough. 'Sibi… suum… munus' is 'to herself, as her own gift', 'suum' being reflexive, since the subject is Proserpina. 'Hoc… ferri' is an accusative and infinitive after 'instituit', 'ordained that this be brought', 'ferri' being passive."""),
(144, 'metallo.',
 """When the first is torn off, not fails a second
golden, and with like metal bursts into leaf a twig.""",
 """When the first is torn away, a second, also of gold, does not fail to appear, and the shoot puts out leaves of the same metal.""",
 """'Primo avulso' is an ablative absolute, 'the first having been torn off'. 'Non deficit alter aureus' is 'a second, golden, does not fail', 'deficit' being 'is lacking'. 'Frondescit' is an inchoative, 'comes into leaf', 'virga' a twig, 'simili… metallo' an ablative of means, 'with like metal'."""),
(146, 'manu;',
 """So high search with your eyes, and duly found
pluck with the hand;""",
 """So search high with your eyes, and when you have found it as the rite demands, pluck it with your hand;""",
 """'Vestiga' is the imperative of 'vestigo', 'track down', 'search out', and 'alte' is 'high', up in the tree. 'Rite' is 'duly', 'according to the proper rite', and 'repertum' is the perfect participle of 'reperio'. 'Carpe' is 'pluck'."""),
(147, 'vocant;',
 """for it itself, willing and easy, will follow,
if the fates call you;""",
 """for it will follow of its own accord, willing and yielding, if the fates are calling you;""",
 """'Namque' is 'for'. 'Ipse' is 'the bough itself', and 'volens facilisque' are predicative, 'willing and easy'. 'Si te fata vocant' has a present indicative in the condition and a future ('sequetur') in the main clause: 'if the fates are calling you'. 'Fata' are the fates, a man's appointed destiny."""),
(148, 'ferro.',
 """otherwise not by any forces
to conquer, nor will you be able with hard iron to tear it off.""",
 """Otherwise no force of yours can overcome it, nor can you wrench it loose with hard iron.""",
 """'Aliter' is 'otherwise'. 'Poteris' governs both infinitives, 'vincere' ('to overcome') and 'convellere' ('to tear loose'), the first with 'non viribus ullis', the second with 'nec… duro… ferro', 'with hard iron', an ablative of means, the blade of an axe or knife."""),
(151, 'pendes.',
 """Besides lies lifeless for you the body of a friend —
alas, you do not know — and pollutes the whole fleet with death,
while advice you seek and at our threshold hang.""",
 """Besides, the lifeless body of a friend of yours lies there — alas, you do not know it — and defiles your whole fleet with death, while you seek counsel and linger at our threshold.""",
 """'Exanimum' is 'lifeless', agreeing with 'corpus' (at 161 Greenough prints 'exanimem': the adjective has both forms, 'exanimus' and 'exanimis', with the same sense). 'Tibi' is a dative of reference, 'for you'. 'Heu nescis' is a parenthesis between dashes. 'Incestat' is 'pollutes', a word for ritual defilement, and 'funere' (ablative) is 'with death'. 'Dum… petis… pendes' is 'while you seek… and hang', the present tense with 'dum'; 'consulta' is a neuter plural participle used as a noun, 'things asked for', 'counsel', 'oracles', and 'pendes' is 'you hang in doubt'. The friend is not named."""),
(152, 'sepulchro.',
 """To his own seats first bring this one back, and bury him in a tomb.""",
 """First bring him back to his own resting place and lay him in a tomb.""",
 """'Hunc' is the friend; 'sedibus… suis' is 'to his own seats', his proper resting place, a dative of the place reached; 'refer' and 'conde' are imperatives ('conde' is 'bury', 'lay away'). 'Sepulchro' is Greenough's spelling (the Latin Library prints 'sepulcro')."""),
(153, 'pecudes;',
 """Lead black beasts;""",
 """Bring black beasts for the sacrifice;""",
 """'Duc' is the short imperative of 'duco'. 'Pecudes' are livestock, here the victims, and 'nigras' is 'black', the colour for offerings to the powers below."""),
(153, 'sunto:',
 """those first expiations let them be:""",
 """Let those be the first atonements:""",
 """'Sunto' is the third-person plural of the future imperative, 'let them be'. 'Ea' is 'those' and refers to the victims, and 'piacula' are 'offerings that make atonement'. The colon leads to the result."""),
(155, 'aspicies.',
 """Thus at last the groves of Styx and the realms impassable to the living
you will behold.”""",
 """Only so will you at last look upon the groves of the Styx and the realms closed to the living.”""",
 """The print has 'aspicies. ”Dixit', a misprint for 'aspicies.” Dixit', corrected here. The mark closing the Sibyl's speech is set after a space and joined to the next word, so t keeps the print and the mark stands at the head of the next unit, while l and i close the speech after 'aspicies.'. 'Sic demum' is 'only so, and then', 'lucos Stygis' are 'the groves of Styx' ('Stygis' is the genitive of 'Styx'), and 'invia vivis' is 'impassable to the living', a dative. 'Aspicies' is a future."""),
(155, 'ore.',
 """She spoke, and with her mouth pressed shut fell dumb.""",
 """So she spoke, and with her lips pressed shut fell mute.""",
 """The print has 'aspicies. ”Dixit', a misprint for 'aspicies.” Dixit', corrected here; the mark at the head of t belongs to the speech just ended, so l and i carry none. 'Dixit' is 'she has spoken', the formula that closes a speech. 'Pressoque… ore' is an ablative absolute, 'her mouth pressed (shut)'; 'obmutuit' is an inchoative perfect, 'became dumb'."""),
(158, 'secum.',
 """Aeneas, with sad countenance, fixed as to his eyes,
goes forward, leaving the cave, and blind
outcomes turns over in his mind with himself.""",
 """Aeneas went forward, leaving the cave, his face sorrowful and his eyes fixed, and turned over in his mind the dark outcomes to come.""",
 """A new paragraph. 'Defixus lumina' is a passive participle with an accusative of respect, a Greek construction, 'fixed as to his eyes' (the eyes held unmoving), and 'maesto… voltu' is 'with sad face'; 'voltu' is Greenough's spelling (the Latin Library has 'vultu'). 'Caecos… eventus' are 'blind outcomes', that is hidden and uncertain ones, and 'volutat' is 'turns over', a frequentative. 'Secum' is 'with himself'."""),
(159, 'figit.',
 """To him faithful Achates
goes as companion, and with equal cares plants his footsteps.""",
 """Faithful Achates walks beside him, sharing his anxiety, and sets his steps beside his own.""",
 """'Cui' is a connecting relative, 'to him', a dative with the verb 'it' (from 'eo', 'goes'). 'Comes' is a predicative noun, 'as companion'. 'Paribus curis' is 'with equal cares', an ablative of manner, since Achates shares Aeneas's worry; 'vestigia figit' is 'fixes his footsteps', 'walks'."""),
(162, 'diceret.',
 """Many things among themselves in varied talk they were weaving,
what comrade lifeless the seer, what body to be buried
she meant.""",
 """They wove much talk between them, in shifting conversation, wondering what lifeless comrade the prophetess meant, and what body needed burial.""",
 """'Serebant' is 'were stringing together', from 'sero', 'to join', so 'sermonem serere' is to carry on a talk. 'Inter sese' is reciprocal. 'Quem socium… quod corpus' are indirect questions with 'diceret', 'she meant', in the subjunctive; 'vates' is the Sibyl; 'humandum' is a gerundive, 'to be buried'. 'Exanimem' is Greenough's form (the Latin Library prints 'exanimum', with the same sense)."""),
(165, 'cantu.',
 """And they Misenus on the dry shore,
when they came, see, by an undeserved death destroyed,
Misenus the son of Aeolus, than whom no other more outstanding
with the bronze to rouse men, and Mars to kindle with song.""",
 """And as they came they saw Misenus lying on the dry shore, cut down by an undeserved death — Misenus, son of Aeolus, whom none surpassed in calling men up with the bronze, or in setting war alight with a tune.""",
 """This is the first time the dead man is named, and the answer to the Sibyl's riddle. 'Illi' is nominative plural, 'they', Aeneas and Achates. 'Ut venere' is 'when they came', 'venere' for 'venerunt'. 'Indigna morte peremptum' is 'destroyed by an undeserved death'. 'Aeoliden' is a Greek accusative of the patronymic, 'son of Aeolus', beginning with the diphthong 'Ae-'. 'Quo non praestantior alter' is an ablative of comparison, 'than whom no other (was) better', followed by two explanatory (epexegetic) infinitives, 'aere ciere viros' ('to rouse men with bronze', that is a trumpet) and 'Martemque accendere cantu' ('to kindle war with song'); 'Martem' stands for war."""),
(167, 'hasta:',
 """Of great Hector this one had been the companion; around Hector
both with the trumpet battles distinguished he went through and with the spear:""",
 """He had been a comrade of great Hector, and at Hector's side went through battle after battle, conspicuous with both horn and spear:""",
 """'Hectoris… comes' is 'companion of Hector', and 'Hectora circum' is a preposition after its noun, with a Greek accusative. 'Lituo' is the 'lituus', a curved war-trumpet, and 'hasta' the spear, both ablatives of means. 'Insignis' is 'conspicuous'; 'obibat' is 'went to meet'. The colon leads to what happened afterwards."""),
(170, 'secutus.',
 """after Achilles the victor had despoiled him of life,
to Dardanian Aeneas himself, the bravest hero,
had joined as a companion, following no lesser things.""",
 """When victorious Achilles had stripped Hector of his life, this bravest of heroes attached himself as a comrade to Dardanian Aeneas, following no lesser cause.""",
 """'Illum' is Hector. 'Vita spoliavit' is 'despoiled of life', the ablative of removal. 'Sese… addiderat' is a pluperfect, 'had attached himself', with 'socium' in apposition, 'as a companion', and 'Dardanio' meaning Trojan. 'Non inferiora secutus' is 'not following lesser things', a litotes: he joined a cause no meaner than Hector's."""),
(174, 'unda.',
 """But then, by chance while with hollow shell he makes the seas sound,
mad, and with song calls to contests the gods,
a rival, having caught him, Triton, if to believe is worthy,
among the rocks the man in foaming wave had plunged.""",
 """But then, as he happened to be making the waters ring with a hollow conch, the madman, and was challenging the gods to a contest with his song, jealous Triton — if it is right to believe it — had seized him and plunged him among the rocks under a foaming wave.""",
 """'Forte' is 'by chance', 'dum personat' is a present with 'dum', 'while he makes sound', and 'cava… concha' a hollow shell used as a trumpet. 'Demens' is 'mad', and he is mad to compete with gods. 'Aemulus… Triton' is 'rival Triton', the sea-god who also blows a shell, and 'exceptum' is the perfect participle of 'excipio', 'having caught him'. 'Si credere dignum est' is a parenthesis, 'if it is right to believe', with which Virgil distances himself from the tale. 'Inmerserat' is Greenough's spelling (the Latin Library prints 'immerserat'), a pluperfect, and 'spumosa… unda' is an ablative of means."""),
(176, 'Aeneas.',
 """So all around with great clamour were murmuring,
especially pious Aeneas.""",
 """So they all crowded round him with a great outcry of grief, and above all loyal Aeneas.""",
 """A new paragraph. 'Ergo' is 'so', 'circum' is an adverb, 'round about', and 'fremebant' is 'were roaring', 'murmuring', here with grief. 'Praecipue' is 'especially', and 'pius' is Aeneas's constant epithet. The verb is held over for 'Aeneas' too."""),
(178, 'certant.',
 """Then the commands of the Sibyl,
no delay, weeping they hasten, and an altar of the tomb
to heap with trees and to raise to the sky they strive.""",
 """Then, with no delay, weeping, they hurry to carry out the Sibyl's commands, and vie in heaping logs for the funeral pyre and raising it to the sky.""",
 """'Iussa' is 'commands' (a perfect participle used as a noun, neuter plural), the object of 'festinant', which here takes an accusative; 'haud mora' is 'no delay', with 'est' left out. 'Aram sepulchri' is 'the altar of the tomb', the funeral pyre. 'Congerere' and 'educere' are infinitives after 'certant', 'they strive to'; 'arboribus' is an ablative of means, 'with trees', 'caelo' a dative of the place toward which, 'to the sky'."""),
(179, 'ferarum;',
 """It is gone into the ancient forest, the deep lairs of wild beasts;""",
 """They go into an ancient forest, the deep haunts of wild beasts;""",
 """'Itur' is an impersonal passive, literally 'it is gone', so 'they go', which you'll see constantly in narrative. 'Stabula alta ferarum' is in apposition to 'silvam', 'the deep lairs of wild beasts'."""),
(182, 'ornos.',
 """Down fall the pines, rings struck with axes the holm-oak,
and ash beams with wedges and the easily split oak
is cleft, they roll up huge from the mountains the mountain-ashes.""",
 """Pines crash down, the holm-oak rings under the blows of axes, beams of ash and oak that splits readily are cleft with wedges, and they roll huge mountain-ash trees down from the heights.""",
 """'Procumbunt piceae' is 'the pines fall forward', and 'ilex' is the holm-oak, an evergreen oak. 'Icta securibus' is 'struck with axes'. 'Fraxineae trabes' are 'beams of ash', and 'fissile robur' is 'splittable oak'; the singular 'scinditur' goes with the nearer subject, and 'cuneis' is an ablative of means, 'with wedges'. 'Advolvunt' is 'roll toward them', with 'ingentis… ornos' (accusative plural in '-is') 'huge mountain ashes' and 'montibus' an ablative of source, 'from the hills'."""),
(184, 'armis.',
 """And no less Aeneas amid such works first
urges on his comrades, and with like tools girds himself.""",
 """And Aeneas too, among such labours, is first to cheer on his comrades, and arms himself with the same tools.""",
 """A new paragraph. 'Nec non' is 'and also', literally 'and not not', a litotes you'll see constantly. 'Opera inter talia' is 'inter talia opera', with the preposition after its noun, and 'primus' is 'first', at the front of the work. 'Accingitur' is a passive with a middle sense, 'girds himself', and 'paribus armis' is 'with equal arms', arms meaning tools, the same ones as the men use."""),
(186, 'precatur:',
 """And these things he himself with his own sad heart turns over,
looking at the forest immense, and thus with voice he prays:""",
 """And he himself turns these thoughts over in his sad heart, looking out on the boundless forest, and prays aloud:""",
 """'Haec' is 'these things', the matter of his thoughts, 'ipse' is 'he himself', alone with his thoughts; 'suo tristi cum corde' has 'cum' between the adjectives and the noun. 'Aspectans' is a frequentative participle, 'gazing at'. Greenough has 'voce', 'with voice', 'aloud'; the Latin Library has 'forte', 'by chance', which would change the sense. 'Inmensam' is Greenough's spelling (the Latin Library prints 'immensam'). The colon opens his prayer."""),
(189, 'est.”',
 """“If now himself to us that golden on the tree bough
would show in a forest so great, since all things truly
alas too much about you the seer, Misenus, has spoken.”""",
 """“If that golden bough would only reveal itself to us now from its tree, in so vast a wood — since all the seer said of you, Misenus, was true, alas, too true.”""",
 """The opening mark begins Aeneas's prayer, closed in this line. 'Si… ostendat' is a wish, the present subjunctive with 'si', 'if only it would show'; 'ille aureus… ramus' is 'that golden bough', with 'arbore' as an ablative of place and 'nemore in tanto' with the preposition between noun and adjective. 'Quando' is 'since', and 'omnia vere' means 'all things (she said) truly'. 'Heu nimium' is 'alas, too much', that is too truly; 'vates' is the Sibyl and 'Misene' a vocative addressed to the dead man. 'Locuta est' is the perfect of the deponent 'loquor'. The prayer rests on the Sibyl's words at 149–152, now seen to have been right about Misenus."""),
]
P = A.part('aeneid-041'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
